-- Sourcing colors generated by pywal
local HOME = os.getenv("HOME") or ""
local colors = {
    backgroundCol = "0xff0c0c0d",
    color0 = "0xff0c0c0d",
    color15 = "0xffaec7df",
}
local wal_colors_file = io.open(HOME .. "/.cache/wal/colors-hyprland", "r")
if wal_colors_file then
    for line in wal_colors_file:lines() do
        local var, val = line:match("^%$([%w_]+)%s*=%s*(%S+)")
        if var and val then
            colors[var] = val
        end
    end
    wal_colors_file:close()
end
